update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-nice/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Nice et dans les Alpes-Maritimes","mecanisme":"La Côte d''Azur passe pour tertiaire. Sa production est pourtant concentrée dans la plaine du Var, à Carros et Saint-Isidore. S''y ajoutent les sites de parfum et de cosmétique de Grasse, et les ateliers de précision entre Cannes et Sophia Antipolis. Nos techniciens itinérants couvrent ce couloir et se déplacent partout en France.","cta":"Demander une intervention à Nice","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs, mécaniciens, électriciens, automaticiens, roboticiens"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental"},{"valeur":"+ 120","libelle":"clients accompagnés, dont plus de 80 réguliers"}]},{"type":"probleme","punchline":"Une ligne de conditionnement s''arrête à Carros au mois d''août. La moitié de votre équipe maintenance est en congés, et l''autre moitié couvre déjà deux sites.","puces":[{"accroche":"L''été vide les ateliers avant de vider les plannings.","texte":"Les congés tombent quand la charge monte, et le préventif saute le premier."},{"accroche":"Le foncier industriel est rare, les sites sont dispersés.","texte":"Entre plaine du Var, Grasse et Cannes, vos équipements ne tiennent pas dans un seul périmètre."},{"accroche":"Parfum et cosmétique imposent la propreté.","texte":"Une intervention mal documentée sur une ligne sensible coûte plus cher que la panne elle-même."},{"accroche":"L''eau et les utilités tournent en continu.","texte":"Stations, réseaux, valorisation des déchets : le service rendu ne se met pas en pause pour une réparation."},{"accroche":"Le recrutement industriel perd face au tertiaire.","texte":"Le bassin attire ailleurs, et vos postes techniques restent ouverts."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Renfort pendant les congés et les pics","texte":", technicien intégré à votre équipe sur la période."},"benefice":"Le préventif de l''été se fait, et votre équipe part vraiment en vacances."},{"prestation":{"accroche":"Dépannage sur site","texte":", recherche de défaut, remise en route, cause racine cherchée."},"benefice":"La ligne repart et le compte rendu explique pourquoi elle s''était arrêtée."},{"prestation":{"accroche":"Interventions documentées en environnement sensible","texte":"propreté, traçabilité, habilitations à jour."},"benefice":"Vos audits trouvent une trace écrite pour chaque passage."},{"prestation":{"accroche":"Utilités et réseaux","texte":"eau, air comprimé, électricité, chasse aux fuites, échangeurs."},"benefice":"Les dérives se lisent sur vos relevés avant de peser sur la facture."},{"prestation":{"accroche":"Automatisme et robotique","texte":"SIEMENS, Schneider, ABB, Fanuc, supervision et rétrofit."},"benefice":"Un automate qui dit non trouve quelqu''un capable de le lire."},{"prestation":{"accroche":"Multi-sites sous contrat unique","texte":", de la plaine du Var à Grasse et Cannes."},"benefice":"Un interlocuteur pour tous vos sites, au même niveau d''exigence."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", pour les installations en service continu."},"benefice":"Un défaut de nuit ne devient pas un arrêt de production au matin."},{"prestation":{"accroche":"Contrat [Zéro arrêt](/offres/zero-arret/)","texte":"visites planifiées, priorité en cas de panne, diagnostic gratuit au départ."},"benefice":"Le préventif entre au planning au lieu d''être repoussé chaque mois."}]},{"type":"deroule","etapes":[{"titre":"Premier contact","texte":"vous décrivez la panne ou le besoin. Rappel dans l''heure aux horaires ouvrés par un chargé d''affaires."},{"titre":"Qualification","texte":"machines, accès, habilitations, contraintes de propreté ou d''horaires. Le champ d''intervention s''écrit avant le chiffrage."},{"titre":"Devis écrit","texte":"périmètre, créneaux, matériel, conditions. Rien ne se découvre en bas de facture."},{"titre":"Intervention","texte":"accueil sécurité, plan de prévention, consignation, diagnostic, réparation, redémarrage sécurisé."},{"titre":"Compte rendu","texte":"opérations, temps passé, pièces, préconisations, versés dans votre outil."},{"titre":"Suivi","texte":"sur contrat, revue de la récurrence par équipement et du respect du plan préventif."}]},{"type":"garanties","puces":[{"accroche":"Le profil vous est présenté avant l''intervention.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation partagés."},{"accroche":"Aucune adresse locale inventée.","texte":"Nous couvrons les Alpes-Maritimes en itinérance depuis le réseau national, et nous le disons au lieu d''afficher une vitrine."},{"accroche":"Un périmètre écrit et des modalités de sortie claires.","texte":"Ce qui est inclus, ce qui ne l''est pas, les conditions d''astreinte, les conditions d''arrêt."}]},{"type":"cta","question":"Besoin d''un renfort pour tenir vos équipements cet été ?","bouton":"Demander une intervention à Nice","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-nice/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Un technicien intégré à l''équipe maintenance pendant les congés d''été","texte":", pour garder les équipements opérationnels en juillet et août","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"},{"titre":"Renfort de 6 mois sur un site de traitement des eaux industrielles à risque chimique","texte":", depuis février 2026","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Maintenance sous contrat d''un parc d''équipements dispersé sur tout le territoire","texte":", depuis février 2024","lienLibelle":"Étude de cas TIMESCOPE : casques de réalité virtuelle","lienHref":"/preuves/timescope/"},{"titre":"1 à 3 techniciens en renfort permanent sur plusieurs sites de production","texte":", depuis octobre 2024","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Nice, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas d''agence dans les Alpes-Maritimes et nous ne prétendons pas le contraire : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et le chargé d''affaires vous dit dès le premier appel si le besoin est tenable."},{"question":"Quelles communes couvrez-vous ?","reponse":"Nice et Saint-Isidore, Carros dans la plaine du Var, Saint-Laurent-du-Var, Cannes, Antibes et Grasse. Au-delà, nos techniciens se déplacent partout en France."},{"question":"Pouvez-vous couvrir plusieurs de nos sites avec un seul contrat ?","reponse":"Oui. Contrat unique, comptes rendus au même format, un interlocuteur. Vos sites de la plaine du Var et du bassin grassois se pilotent ensemble."},{"question":"Que se passe-t-il en cas de panne la nuit ou un jour férié ?","reponse":"L''astreinte 24/24 et 7/7 prend l''appel et mobilise un technicien. Le circuit d''appel et l''ordre des priorités sont écrits au devis, site par site."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"L''offre Zéro arrêt fonctionne en abonnement, trois niveaux de couverture, sur devis, engagement type 6 mois renouvelable. Le diagnostic de départ est gratuit."},{"question":"Faites-vous aussi les utilités et le chauffage, ventilation, climatisation des bâtiments ?","reponse":"Nos techniciens interviennent sur les utilités et la filtration industrielle qui servent la production. Le cœur du métier reste l''équipement de production, pas la gestion de bâtiment tertiaire."}]},{"type":"ctaFinal","question":"Besoin d''un partenaire technique qui couvre vos sites de Carros à Grasse ?","bouton":"Demander une intervention à Nice","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-nice/';
